import{_ as a,o,c as t,ag as l}from"./chunks/framework.BpFM782D.js";const p=JSON.parse('{"title":"release","description":"","frontmatter":{},"headers":[],"relativePath":"skills/release.md","filePath":"skills/release.md"}'),r={name:"skills/release.md"};function i(d,e,s,c,n,h){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="release" tabindex="-1">release <a class="header-anchor" href="#release" aria-label="Permalink to &quot;release&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>release</td></tr><tr><td>說明</td><td>版本發布流程。涵蓋版本號管理、changelog 產生、tag 建立與發布。</td></tr><tr><td>來源目錄</td><td><code>skills/release/</code></td></tr></tbody></table><hr><h1 id="release-1" tabindex="-1">Release <a class="header-anchor" href="#release-1" aria-label="Permalink to &quot;Release&quot;">​</a></h1><p>更新版本號、提交、推送、打標籤——讓 CI 負責發布。</p><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><ul><li>/release — 從上次標籤以來的 commit 自動偵測 bump 類型</li><li>/release patch — 強制 patch bump（1.2.3 → 1.2.4）</li><li>/release minor — 強制 minor bump（1.2.3 → 1.3.0）</li><li>/release major — 強制 major bump（1.2.3 → 2.0.0）</li></ul><h2 id="步驟" tabindex="-1">步驟 <a class="header-anchor" href="#步驟" aria-label="Permalink to &quot;步驟&quot;">​</a></h2><h3 id="_1-決定-bump-類型" tabindex="-1">1. 決定 bump 類型 <a class="header-anchor" href="#_1-決定-bump-類型" aria-label="Permalink to &quot;1. 決定 bump 類型&quot;">​</a></h3><p>若未提供參數，從上次標籤以來的 commit 自動偵測。執行 git log 查看上次標籤後的 commit 訊息。</p><p>Bump 規則：</p><ul><li>若有任何 commit 以 &quot;feat:&quot; 開頭 — bump <strong>minor</strong></li><li>若只有 fix/chore/docs/refactor/perf/ci/test commit — bump <strong>patch</strong></li><li>若任何 commit body 中有 &quot;BREAKING CHANGE&quot; — bump <strong>major</strong></li></ul><h3 id="_2-更新-package-json-中的版本號" tabindex="-1">2. 更新 package.json 中的版本號 <a class="header-anchor" href="#_2-更新-package-json-中的版本號" aria-label="Permalink to &quot;2. 更新 package.json 中的版本號&quot;">​</a></h3><p>讀取當前版本，計算新版本。僅編輯 package.json。</p><h3 id="_3-更新-changelog-md-若檔案存在則為必要步驟" tabindex="-1">3. 更新 CHANGELOG.md（若檔案存在則為必要步驟） <a class="header-anchor" href="#_3-更新-changelog-md-若檔案存在則為必要步驟" aria-label="Permalink to &quot;3. 更新 CHANGELOG.md（若檔案存在則為必要步驟）&quot;">​</a></h3><p><strong>你必須執行此步驟。不可跳過。</strong></p><ol><li>檢查 repo 根目錄是否存在 <code>CHANGELOG.md</code> — 執行 <code>ls CHANGELOG.md</code></li><li>若存在，你必須更新： a. 讀取 <code>CHANGELOG.md</code> 的完整內容 b. 執行 <code>git log --oneline &amp;lt;last-tag&gt;..HEAD</code> 收集上次標籤後的所有 commit c. 使用 Edit 工具，在<strong>檔案標頭之後</strong>（在 <code>格式基於...</code> 行或等效的前言之後），<strong>在</strong>任何現有 <code>## [</code> 區段<strong>之前</strong>，插入新的版本區段 d. 格式遵循 Keep a Changelog： <ul><li><code>## [X.Y.Z] - YYYY-MM-DD</code></li><li>依類型分組：<code>### Added</code>（feat）、<code>### Fixed</code>（fix）、<code>### Changed</code>（refactor/chore/perf）、<code>### Removed</code></li><li>以 commit 描述（去掉類型前綴）作為項目文字</li><li>語言與現有條目一致</li></ul></li><li>若 <code>CHANGELOG.md</code> 不存在，跳過此步驟</li></ol><h3 id="_4-提交並推送" tabindex="-1">4. 提交並推送 <a class="header-anchor" href="#_4-提交並推送" aria-label="Permalink to &quot;4. 提交並推送&quot;">​</a></h3><p>暫存 package.json 與 CHANGELOG.md（若已更新），以 &quot;chore: bump version to X.Y.Z&quot; 為訊息提交，然後推送。</p><h3 id="_5-打標籤並推送標籤" tabindex="-1">5. 打標籤並推送標籤 <a class="header-anchor" href="#_5-打標籤並推送標籤" aria-label="Permalink to &quot;5. 打標籤並推送標籤&quot;">​</a></h3><p>重要：在推送後再打標籤，讓 CI 取得正確的 package.json。</p><p>建立 vX.Y.Z 標籤，然後推送標籤至 origin。</p><h3 id="_6-報告" tabindex="-1">6. 報告 <a class="header-anchor" href="#_6-報告" aria-label="Permalink to &quot;6. 報告&quot;">​</a></h3><p>印出摘要，包含新版本號、commit hash、標籤名稱，並說明 CI 將自動發布。</p><h2 id="規則" tabindex="-1">規則 <a class="header-anchor" href="#規則" aria-label="Permalink to &quot;規則&quot;">​</a></h2><ul><li>絕不在本地執行 npm publish — CI 負責處理</li><li>絕不在推送版本 bump commit 之前打標籤</li><li>絕不修改或強制推送 CI 已處理的標籤</li><li>若找不到 feat 或 fix commit，在繼續前詢問使用者</li></ul>',26)])])}const u=a(r,[["render",i]]);export{p as __pageData,u as default};
